/**
 * Generates database/seed.sql from the shared content JSON (single source of truth).
 * Usage: npm run db:seed:generate
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import mysql from 'mysql2';
import { components, damageScenarios, suspensions } from '@suspension-lab/shared';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const e = (v: unknown) => mysql.escape(v as string);
const j = (v: unknown) => mysql.escape(JSON.stringify(v));

const lines: string[] = [
  '-- AUTO-GENERATED by scripts/generate-seed.ts from shared/content/*.json — do not edit by hand.',
  'SET NAMES utf8mb4;',
  'START TRANSACTION;',
  'DELETE FROM component_education;',
  'DELETE FROM damage_scenarios;',
  'DELETE FROM suspension_components;',
  'DELETE FROM component_includes;',
  'DELETE FROM components;',
  'DELETE FROM suspension_types;',
  '',
];

const compId = new Map<string, number>();
components.forEach((c, i) => compId.set(c.id, i + 1));

lines.push('-- components');
for (const c of components) {
  lines.push(
    `INSERT INTO components (id, slug, name, name_en, category, summary, function_text, working_principle, location, sort_order) VALUES (${compId.get(c.id)}, ${e(c.id)}, ${e(c.name)}, ${e(c.nameEn)}, ${e(c.category)}, ${e(c.summary)}, ${e(c.function)}, ${e(c.workingPrinciple)}, ${e(c.location)}, ${c.sortOrder});`,
  );
}

lines.push('', '-- component_includes');
for (const c of components) {
  (c.includes ?? []).forEach((child, i) => {
    lines.push(`INSERT INTO component_includes (parent_component_id, child_component_id, sort_order) VALUES (${compId.get(c.id)}, ${compId.get(child)}, ${i + 1});`);
  });
}

lines.push('', '-- component_education');
const eduTypes = [
  ['failureModes', 'failure_mode'],
  ['symptoms', 'symptom'],
  ['consequences', 'consequence'],
  ['inspection', 'inspection_step'],
] as const;
for (const c of components) {
  for (const [field, type] of eduTypes) {
    c[field].forEach((body, i) => {
      lines.push(`INSERT INTO component_education (component_id, content_type, title, body, sort_order) VALUES (${compId.get(c.id)}, '${type}', NULL, ${e(body)}, ${i + 1});`);
    });
  }
  c.terms.forEach((t, i) => {
    lines.push(`INSERT INTO component_education (component_id, content_type, title, body, sort_order) VALUES (${compId.get(c.id)}, 'term', ${e(t.term)}, ${e(t.definition)}, ${i + 1});`);
  });
}

lines.push('', '-- suspension_types');
suspensions.forEach((s, i) => {
  const sid = i + 1;
  lines.push(
    `INSERT INTO suspension_types (id, slug, name, name_en, tagline, axle_position, independence, summary, description, how_it_works, typical_applications, advantages, disadvantages, steerable, model_key, sort_order) VALUES (${sid}, ${e(s.id)}, ${e(s.name)}, ${e(s.nameEn)}, ${e(s.tagline)}, ${e(s.axlePosition)}, ${e(s.independence)}, ${e(s.summary)}, ${e(s.description)}, ${j(s.howItWorks)}, ${j(s.typicalApplications)}, ${j(s.advantages)}, ${j(s.disadvantages)}, ${s.steerable ? 1 : 0}, ${e(s.modelKey)}, ${s.sortOrder});`,
  );
  for (const l of s.components) {
    const cid = compId.get(l.componentId);
    if (!cid) throw new Error(`Unknown component ${l.componentId}`);
    lines.push(
      `INSERT INTO suspension_components (suspension_type_id, component_id, local_name, role_description, quantity_note, sort_order) VALUES (${sid}, ${cid}, ${e(l.localName ?? null)}, ${e(l.roleDescription)}, ${e(l.quantityNote ?? null)}, ${l.sortOrder});`,
    );
  }
});

lines.push('', '-- damage_scenarios');
damageScenarios.forEach((d, i) => {
  lines.push(
    `INSERT INTO damage_scenarios (id, slug, component_id, title, short_title, severity, normal_condition, damaged_condition, failure_description, symptoms, safety_implications, inspection_steps, sim_kind, sim_params, recommended_mode, sort_order) VALUES (${i + 1}, ${e(d.id)}, ${compId.get(d.componentId)}, ${e(d.title)}, ${e(d.shortTitle)}, ${e(d.severity)}, ${e(d.normalCondition)}, ${e(d.damagedCondition)}, ${e(d.failureDescription)}, ${j(d.symptoms)}, ${j(d.safetyImplications)}, ${j(d.inspection)}, ${e(d.simulation.kind)}, ${j(d.simulation.params)}, ${e(d.simulation.recommendedMode)}, ${d.sortOrder});`,
  );
});

lines.push('', 'COMMIT;', '');
const out = resolve(root, 'database/seed.sql');
writeFileSync(out, lines.join('\n'), 'utf8');
console.log(`Wrote ${out} (${lines.length} lines)`);
